        placeholder,
        required = false,
        autocomplete,
        helpText = "",
        errorMessage = ""
      }) => `
        <div class="form-field" data-field="${id}">
          <label for="${id}">
            <span>${label}</span>
            ${required ? '<span class="required-indicator">*</span>' : ""}
          </label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            placeholder="${placeholder}"
            ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
            ${required ? "required" : ""}
          />
          ${helpText ? `<p class="field-help">${helpText}</p>` : ""}
          <p class="field-error" aria-live="polite">${errorMessage}</p>
        </div>
      `;

      const Header = () => `
        <header>
          <p class="eyebrow">Support</p>
          <h1>Contact our support team</h1>
          <p class="intro">
            Share your details and we’ll follow up as soon as possible with the right next step.
          </p>
        </header>
      `;

      const ContactForm = () => `
        <form id="support-form" novalidate>
          ${createField({
            id: "fullName",
            label: "Full name",
            placeholder: "Jordan Lee",
            required: true,
            autocomplete: "name",
            errorMessage: "Please enter your full name."
          })}
          ${createField({
            id: "email",
            label: "Email address",
            type: "email",
            placeholder: "jordan@example.com",
            required: true,
            autocomplete: "email",
            errorMessage: "Please enter a valid email address."
          })}
          ${createField({
            id: "phone",
            label: "Phone number",
            type: "tel",
            placeholder: "(555) 123-4567",
            autocomplete: "tel",
            helpText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
            errorMessage: "Please use a valid phone number format."
          })}
          <div class="actions">
            <button type="submit">Submit</button>
          </div>
          <div class="success-banner" id="success-banner" aria-live="polite">
            Thanks — your support request is ready to send.
          </div>
        </form>
